local config = {
  str_season_maze_s2_title = "꿈의 잔향",
  str_season_maze_s2_subtitle = "꿈의 잔향",
  str_season_maze_s2_even_desc_1001 = "당신은 멍하니 주변의 모습을 바라보았다... 적도, 보물도... 아무것도 없었다. 「쿵!」 소리와 함께, 보이지 않는 공기의 벽이 앞으로 나아가려는 당신을 제자리에 굳게 막아섰다.\n\n「상황 분석 중... 해당 영역은 에너지 파동이 매우 활발해 정확하게 위치를 파악할 수 없습니다.」 계몽자의 얼굴은 고속 연산으로 인해 빨갛고 뜨겁게 변했다. 「이곳은 미지의 영역입니다. 프랜시스 교수님은 이런 꿈의 영역이 주는 불확실성을 좋아한다고 하셨습니다. 게다가 이곳에는 가끔씩 꿈의 주인이 남긴 그림자도 비치곤 합니다.」\n\n그 말은 여기서 당신의 친구를 만날 수 있을지도 모른다는 뜻 같았다.\n\n「이탈 경로 3종을 분석했습니다. 선택해 주세요. 참고로 경로마다 다른 보상이 주어집니다. 최악의 가정을 해 두시기 바랍니다. 그렇지 않으면 게임 경험에 영향을 줄 수 있습니다.」\n\n당신의 의문을 간파한 듯, 계몽자는 이어서 말했다. 「최악의 가정은 보상이 없는 경우를 말합니다.」 당신은 생각했다. 결과가 나빠봤자 그 정도라면 선택은 쉬울 것이라고 말이다... 아마도.",
  str_season_maze_s2_even_desc_1002 = "「상황 분석 중...」 계몽자는 마치 수많은 영롱한 보물들이 바람에 흘러가고 있다는 듯이 주위의 공기를 진지하게 응시하고 있었다. 비록 당신에게는 아무것도 보이지 않았지만, 적어도 이곳이 새로운 미지의 영역이라는 것만은 알 수 있었다.\n\n「이탈 경로 3종을 분석했습니다. 선택해 주세요.」\n\n마치 당신을 격려하려는 듯, 계몽자는 당신의 옷자락을 끌어당기며 목소리를 낮추었다. 「귀띔해 드리겠습니다. 계몽자는 아버지가 이번에 꿈의 금화를 얻을 수 있을 것 같다는 예감이 듭니다.」",
  str_season_maze_s2_even_desc_1003 = "「상황 분석 중...」 그동안 미지의 영역에서 「불확실성」으로 인해 자극적인 느낌을 경험했기 때문인지, 당신은 계몽자가 어떤 계산 결과를 내놓을지 기대되기 시작했다.\n\n「정보 결합, 아버지도 프랜시스 교수님처럼 미지의 영역을 좋아하게 되었군요.」\n\n계몽자는 이 결과에 무척 만족하는 듯했다. 「설명, 이제 아버지는 알게 되었을 것입니다. 계몽자는 아버지를 속이지 않았습니다. 꿈의 세계 속 게임은 무척 재미있습니다. 아닙니다, 계몽자가 받는 느낌은 없습니다. 그러나 계몽자는 드림 워커의 느낌을 짐작할 수 있습니다.」",
  str_season_maze_s2_even_desc_1004 = "계몽자는 바닥에 쪼그려 앉아 모래 한 움큼을 쥐어 들었다.\n\n「설명, 프랜시스 교수님에게 들은 적이 있습니다. 바닷속에는 부드러운 마음씨를 가진 한 생물이 있는데, 자신의 고통이 담긴 눈물을 체내의 모래에 스며들게 해서 한층 한층 감싸고, 그렇게 그 생물의 고통은 아름다운 진주로 변한다고 합니다.」\n\n계몽자는 잠시 멈추었고, 이 순간 그녀는 마치 동화 듣기를 좋아하는 평범한 소녀처럼 보였다. 「사실 꿈의 세계에서도 비슷한 물건이 있답니다.」",
  str_season_maze_s2_even_desc_1005 = "「정보 결합 중, 악몽은 좋은 꿈과 다릅니다.」\n\n그것은 물론 다른 것이었고, 당신에게는 생각할 필요조차 없이 단정할 수 있는 사실이었다. 그러나 계몽자는 수많은 정보를 수집해야만 이러한 결론을 도출할 수 있었다.\n\n「오직 악몽 속에서만 꿈의 주인의 고통이 판타즘 스톤으로 만들어집니다.」 그제서야 당신은 계몽자가 무엇을 생각했는지 깨달았다.\n\n이윽고 당신은 계몽자가 꿈의 의미를 알고 있는지, 그녀가 자신의 꿈을 가질 수 있는지 궁금해지기 시작했다.",
  str_season_maze_s2_even_desc_1006 = "「또 만났군요.」 심판기사의 제복을 입은 이리돈이 당신 앞에 서 있었고, 비록 우연히 만난 것이라고 했지만, 왠지 그녀는 오랫동안 당신을 기다리고 있었던 것 같다.\n\n「아무것도 아니에요. 그저 최근에 좋은 물건을 얻게 됐는데, 당신이 어떤 걸 좋아할지 모르겠어서요.」 그녀는 잠시 말을 멈췄다. 「역시 당신에게 선택권을 주는 게 공평하겠죠.」",
  str_season_maze_s2_even_desc_1007 = "「당신 뒤의 여자애는...」 이리돈은 경계하는 눈빛으로 당신을 보았다. 비록 그 엄숙한 표정을 보인 것은 짧은 순간이었지만, 그럼에도 당신은 알아챌 수 있었다.\n\n「미안해요. 최근 인신매매 사건을 맡게 돼서 저도 모르게 그만...」 이리돈은 계몽자의 머리를 쓰다듬은 뒤 당신을 바라보았다. 「당신 곁에서 조금도 떨어지려 하지 않는 걸 보면 당신을 무척 중요한 사람으로 여기고 있는 거겠죠.」",
  str_season_maze_s2_even_desc_1008 = "「도와줘서 고마워요!」 이리돈은 검을 다시 칼집에 꽂고, 바닥에 쓰러진 용의자를 묶었다.\n\n「당신이 나타나서 길을 막아주지 않았으면, 이 사람을 잡으려고 한참을 더 쫓아야 했을지도 몰라요.」 비록 그렇게 말했지만, 이리돈은 전혀 지친 기색이 없었다.\n\n「시간이 없어서 지금은 이것밖에 안 가지고 있네요. 괜찮으면 하나 골라서 가져가세요.」",
  str_season_maze_s2_even_desc_1009 = "「제시간에 왔군요.」 목소리를 따라가자 이리돈이 당신을 향해 달려오는 것이 보였고, 그녀의 붉게 물든 뺨 위로는 땀방울이 흐르고 있었다.\n\n「오늘 훈련 시간이 절반 남았는데, 격투 연습을 할 상대가 없어서 걱정이에요.」 이리돈이 이렇게 쾌활한 미소를 짓는 모습은 보기 드물었다. 「당신 약점은 뭐죠? 제가 대련 파트너가 돼 줄게요.」",
  str_season_maze_s2_even_desc_1010 = "「심판기사라면 그저 강인한 육체만으로는 부족해요.」\n\n눈썹을 찌푸린 이리돈의 얼굴에는 엄숙함이 감돌았다. 「법전, 우린 언제나 법전을 마음에 새겨야만 해요. 그래야 중요한 순간에 죄인을 제압하고 정의를 실현할 수 있죠.」\n\n이리돈은 정말 한 순간도 긴장을 풀지 않는 것 같다.",
  str_season_maze_s2_even_desc_1011 = "이리돈은 손에 들린 하얀 구슬을 멍하니 바라보다가, 당신이 다가오는 것을 보고 무의식적으로 손을 꽉 쥐었다. 「크흠... 사람 없는 곳에서 좀 있으려고 했는데, 당신 눈에 띌 줄은 몰랐네요.」\n\n「그런 표정으로 보지 마세요. 전 정말 괜찮으니까요.」 그녀는 미소를 지으며 손바닥을 폈다. 「하지만 이 아름다운 구슬은 왠지 제 슬픔 속에서 힘을 얻고 있는 것 같네요.」",
  str_season_maze_s2_even_desc_1012 = "「이 구슬이 정말 우리를 보호하는 힘이 될 수 있다는 건가요?」 이리돈은 당신의 설명을 듣고도 별로 놀라지 않은 것 같았다.\n\n「그렇군요... 하지만 당신도 굳이 소중한 물건을 가지고 교환할 필요는 없없어요. 계속 고집을 부린다면 저도 더 주는 수밖에 없을 거예요.」",
  str_season_maze_s2_even_desc_1013 = "「윙」하는 소리와 함께 갑자기 머리가 조여오는 것이 느껴졌고, 눈앞의 계몽자는 갑자기 다섯, 여섯, 일곱, 여덟, 아홉... 개의 분신이 생긴 것 같았다...\n\n「상황 분석 중...」 당신은 계몽자의 얼굴이 잘 보이지 않았다. 그러나 착각인지는 몰라도 계몽자의 목소리가 평소보다 더 긴장해서 떨리는 것 같았다. 「경고, 드림 워커는 꿈의 세계에서 충분한 턴 수를 유지해야 합니다. 그래야만 꿈의 세계에서의 안정적인 활동을 보장할 수 있습니다.」\n\n당신이 정신을 차리자, 계몽자는 그제서야 눈 가리고 아웅 하듯이 해명했다. 「알림, 드림 워커의 안정은 계몽자의 안정에도 영향을 줄 수 있습니다. 계몽자가 고장 나지 않도록 드림 워커는 꿈의 세계 속 턴 관리에 주의해야 합니다.」",
  str_season_maze_s2_even_desc_1014 = "「확인, 프랜시스 교수님이 왜 꿈의 세계 보조 모듈을 개발하셨는지 궁금하신 건가요?」\n\n당신이 고개를 끄덕이자, 계몽자는 무척 열심히 기억을 떠올리는 듯 두 눈을 감았다... 아마 그녀는 지금 천만 년간 저장된 정보를 검색하고 있을지도 모른다.\n\n「답변, 추방된 아이테르들은 일종의 히스테리에 시달렸습니다. 이를 치료하기 위해 드림 워커였던 프랜시스 교수는 환자의 꿈으로 들어갔습니다. 드림 워커가 꿈의 세계에서 행동하는 것은 목숨이 걸린 위험한 일이며, 따라서 꿈의 세계 속 에너지 파동을 정확히 조사하고 모니터링할 수 있는 보조 도구가 반드시 필요합니다.」\n\n「이러한 이유로 프랜시스 교수님은 계몽자를 위해 꿈의 세계 보조 모듈을 개발하셨습니다.」",
  str_season_maze_s2_even_desc_1015 = "「답변, 프랜시스 교수님은 과학 연구만이 아이테르를 구할 수 있다고 믿으셨습니다. 그러나 한편으로는 세상에 관측과 연구가 불가능한 신비로운 힘이 존재한다고 믿으셨습니다...」\n\n「...아닙니다, 아버지가 이해하는 신학이 아닙니다. 신비로운 힘이 신비로운 이유는 현재의 과학 기술로는 이를 관측하고 연구할 수 없기 때문입니다.」\n\n프랜시스 교수에 대한 이야기가 나오자, 당신은 계몽자가 프랜시스 교수에 대한 「괴로운 정크 파일」을 삭제했던 것을 떠올리지 않을 수 없었다.\n\n계몽자는 갑자기 무언가를 민감하게 눈치챈 듯 말했다. 「상황 분석 중... 계몽자가 정크 파일을 유지하기를 아버지가 원한다면, 음성 명령으로 관련 설정을 진행할 수 있습니다.」\n\n깜짝 놀란 당신은 설마 계몽자가 「감응 모듈」 같은 것을 설치한 것은 아닐까 생각했다.",
  str_season_maze_s2_even_desc_1016 = "계몽자는 입술을 살짝 열었다가 얼른 닫았다. 그녀는 뭔가 물어보고 싶은 듯했지만, 명령 입력이 없어 대화를 먼저 시작할 수 없었다.\n\n당신의 동의를 받은 그녀는 마침내 입을 열었다. 「질문, 계몽자는 알고 싶습니다. 외부 세계도 이 꿈의 세계처럼 똑같이 생겼습니까?」\n\n생각해 보니 계몽자는 한 번도 그녀가 「태어난」 탑을 떠난 적이 없었다. 당신은 그녀에게 바깥세상은 훨씬 더 넓다고 말했고, 또한 나중에 그녀를 데리고 산과 바다... 세계 곳곳을 들러봐 주겠다고 약속했다.\n\n「알림, 그때까지 부디 아버지가 자신의 능력 향상에 전념해 주시길 바랍니다.」 비록 계몽자는 무표정한 얼굴로 당신에게 주의를 주었지만, 그녀 뒤의 작은 큐브 속 폭죽이 터지는 이미지는 이미 그녀의 심정을 폭로하고 있었다.\n\n사실 당신은 진작부터 계몽자가 그저 평범한 기계가 아니라고 느끼고 있었다.",
  str_season_maze_s2_even_desc_1017 = "당신은 계몽자가 그동안 어떤 꿈의 세계들에 가 보았는지 궁금했다.\n\n「정보 검색 중...」 계몽자는 눈을 감았다가 다시 번쩍 뜨고 말했다. 「죄송합니다. 아버지는 아직 관련 정보를 개방할 권한이 없습니다.」 하지만 당신에게 권한이 없다면, 지금 이 세상에 권한을 가진 사람이 누가 있을까.\n\n「저의 제조자인 프랜시스 교수님이 설정하신 규칙입니다. 프랜시스 교수님은 꿈의 세계에서 활동하며 충분한 경험치를 얻어야만, 강한 심장과 비범한 지혜를 단련해서 고대 아이테르의 복잡한 꿈의 세계를 견뎌낼 수 있다고 하셨습니다.」\n\n계몽자는 손바닥을 당신의 어깨에 얹었다. 「정보 결합 중... 계몽자는 언젠가 아버지가 권한을 획득할 수 있을 거라고 믿습니다.」",
  str_season_maze_s2_even_desc_1018 = "「정보 검색 중...」 당신의 질문에 계몽자는 늘 모든 답을 주려고 노력했지만, 이번 검색 시간은 그 어느 때보다도 길었다.\n\n「죄송합니다. 계몽자의 데이터베이스에는 계몽자의 에너지원에 대한 자료가 저장되어 있지 않습니다. 하지만 안심하세요, 계몽자의 가동 이력을 토대로 추측한다면, 적어도 아버지가 살아 있는 동안에는 계몽자가 에너지원 문제로 인해 다운될 일은 없을 것입니다.」\n\n...어처구니없는 대답을 들은 당신은 안심해야 할지, 말아야 할지 알 수 없었다.",
  str_season_maze_s2_even_desc_1019 = "당신은 예전에 이미 와 보았던 이 꿈의 세계에 아이테르 스타일로 보이는 도구와 공간이 새로 생겼다는 것을 깨달았다.\n\n「답변, 꿈의 세계에서는 구역에 따라 다른 에너지 파동을 보입니다. 드림 워커들이 쉽게 활동할 수 있도록, 계몽자는 동일한 에너지 파동을 가진 구역에 표식을 생성합니다. 계몽자의 데이터베이스에는 아이테르 스타일의 설비 모형만 있기 때문에, 아이테르 스타일의 물품으로 에너지 파동을 형상화할 수밖에 없습니다.」\n\n계몽자는 잠시 멈추었다가 마치 무슨 잘못이라도 한 것처럼 조심스럽게 물었다. 「질문, 다른 양식으로 바꿔드릴까요?」\n\n하지만 당신은 이대로가 좋을 것 같았다.\n\n이렇게 하면 적어도 꿈속에서라도 진짜 「집」을 가진 느낌이 들었기 때문이다.",
  str_season_maze_s2_even_desc_1020 = "귀환의 탑에서 보았던 앵무조개가 갑자기 생각난 당신은 돌아서서 계몽자에게 물었다.\n\n계몽자는 눈을 감았다. 「정보 검색 중...」\n\n그러나 이번에는 금방 눈을 뜨고 당신을 바라보았다. 「아버지의 설명으로 보았을 때, 말씀하시는 물건은 노틸러스입니다. 일반적으로 아이테르는 한 개 또는 여러 개의 노틸러스를 가지고 있습니다. 노틸러스의 수는 아이테르가 지닌 재산에는 영향을 미치지 않지만, 희귀한 외관의 노틸러스는 그 자체의 가치를 넘어 일종의 수집품이 될 정도로 각광받았습니다. 하지만 계몽자는 아버지에게 제안합니다. 투자는 신중해야 합니다.」\n\n비록 지금의 노틸러스는 한때 아이테르 사회에서 가졌던 실용적 가치를 잃은 지 오래지만, 계몽자의 말은 왠지 지금 시대에도 그대로 적용되고 있는 듯하다.",
  str_season_maze_s2_even_desc_1021 = "계몽자는 현재 대륙에서 유통되고 있는 화폐가 나이티움이라는 말을 들었지만, 계몽자 주변의 큐브들은 놀라거나 하는 반응이 없었다.\n\n설마 계몽자는 이 사실을 이미 예상한 것일까.\n\n「답변, 계몽자는 통화란 사회가 일정한 단계로 발전하며 탄생하는 필연적인 산물이라는 것을 알고 있습니다. 그러나 계몽자에게 있어 화폐는 가치를 지니지 않습니다.」\n\n그렇다면 계몽자에게는 대체 무엇이 가치가 있는 것일까.\n\n계몽자의 얼굴이 다시 붉어지고 뜨거워지기 시작했다. 그것은 그저 「두뇌」가 빠르게 가동하고 있기 때문이라는 것을 당신은 알고 있었다. 「답변, 계몽자는 이 질문에 대한 답을 찾지 못했습니다. 그러나 계몽자는 과거의 정보를 바탕으로 아버지의 동행과 칭찬이 계몽자에게 가장 가치 있는 화폐라고 추측합니다.」",
  str_season_maze_s2_even_desc_1022 = "당신은 꿈의 세계에서 이곳을 탐색하는 데 도움이 되는 물건들을 주워 본 적이 있었다. 그러나 그 물건들은 이 세계에 원래 존재했을 물건 같지 않았다.\n\n「답변, 꿈의 에너지 흐름은 이 세계에만 국한되지 않습니다. 비록 원리는 알려지지 않았지만, 연구에 따르면 모든 꿈의 세계의 에너지는 모종의 규칙에 따라 서로 교환되고 있습니다. 그 물건들은 꿈의 에너지 흐름에 따라 서로 다른 꿈의 세계로 떠밀려 온 것이며, 어떤 꿈의 세계에도 속하지 않기 때문에 그것들을 가지고 갈 수 있는 것입니다.」\n\n그것들은 대체 어디서 온 것들일까.\n\n당신이 갈피를 잡지 못하자 계몽자는 이어서 대답했다. 「그것들은 모두 과거의 드림 워커들이 잃어버린 보물들입니다.」",
  str_season_maze_s2_even_desc_1023 = "꿈의 세계에 들어온 지 이미 오랜 시간이 지났다. 대체 이곳의 여정은 언제 끝나는 것일까.\n\n계몽자는 당신의 피로를 감지했다. 「잠깐 쉬어도 됩니다. 꿈의 에너지 균형을 회복하는 것은 하루아침에 이루어지는 일이 아닙니다. 일반적으로 꿈의 세계에는 종종 여러 개의 단계가 존재합니다. 꿈의 주인이 현실에서 자신을 더 깊게 가둬버릴수록, 꿈의 단계도 늘어납니다. 하지만 꿈의 에너지가 균형을 되찾으면 현실에서도 더 뚜렷하게 호전됩니다.」\n\n계몽자는 조금 더 가까이 다가왔다. 「서술, 아버지가 피곤하시다면 계몽자는 언제든지 아버지에게 따뜻한 음료를 준비해 드릴 수 있습니다.」",
  str_season_maze_s2_even_desc_1024 = "꿈의 세계를 깊이 탐색해 나가면서, 당신은 점점 더 꿈의 세계 속 규칙에 적응하고 있는 자신을 발견하게 되었다.\n\n「알림, 꿈의 세계 속 규칙에 따라, 아버지는 알고 있는 오로리안을 떠올려서 그들을 불러내고 아버지를 돕게 할 수 있습니다. 그러나 그들은 결코 오로리안 본인이 아니라는 점을 잊지 마세요. 그리고 꿈속이기 때문에 뭐든지 마음대로 할 수 있다고도 생각하지 마세요. 비록 계몽자의 도움이 있다고 해도, 꿈의 세계 속에 존재할 수도 있는 위험을 무시해서는 안 됩니다.」\n\n당신은 계몽자가 말하는 속도가 달라진 것에 신경이 쓰였다. 「이상의 내용은 꿈의 세계 보조 모듈이 일정 단계가 개방되면 필수적으로 진행되는 안내이며, 아버지에 대한 계몽자의 판단을 의미하지 않습니다.」",
  str_season_maze_s2_even_desc_1025 = "당신은 계몽자가 당신을 등진 채로 그녀 옆에 있는 큐브에 어떤 수치를 기록하고 있는 것을 발견했다...\n\n「경고, 가까이 오지 마세요!」\n\n누군가 자신에게 다가오는 것을 느낀 계몽자는 갑자기 볼륨을 높여 경고했지만, 다가온 사람이 당신임을 확인한 계몽자의 볼륨은 다시 정상으로 돌아왔다. 「서술, 안심하세요. 계몽자는 꿈의 세계 속 아버지의 행동을 공정하고 객관적으로 평가해서, 그에 상응하는 드림 포인트를 기록할 것입니다.」\n\n당신은 그제서야 계몽자가 자신의 일거수일투족을 관찰하면서 점수까지 매기고 있었다는 사실을 깨달았다.\n\n「설명, 본 작업은 계몽자가 제공하는 추가 보조 기능입니다. 이를 통해 아버지의 꿈의 세계 속 행동 능력을 더 잘 모니터링할 수 있습니다. 만약 일정한 기준을 충족한다면, 계몽자는 아버지에게 추가 보상을 제공할 것입니다.」\n\n역시 계몽자를 얕봐서는 안 될 일이다. 그녀는 철두철미한 훈련의 대가다.",
  str_season_maze_s2_even_desc_1026 = "계몽자의 안내를 받은 당신은 텅 빈 것처럼 보이는 공기 속에서 왠지 수많은 「별」들이 반짝이며 바람에 떠돌고 있는 것을 발견했다.\n\n「서술, 그것은 꿈의 세계의 에너지를 구성하는 최소 입자입니다. 꿈의 금화는 꿈의 세계의 규칙을 통해 아버지가 원하는 다른 물건으로 변화할 수 있습니다...」\n\n당신이 의구심을 품자 계몽자는 말을 바꾸어 설명했다. 「꿈의 금화는 쉽게 말해서 꿈의 세계 속 통용 화폐입니다. 단, 꿈의 금화는 많이 모을수록 좋지만, 계몽자는 과도한 축재를 권장하지 않습니다.」",
  str_season_maze_s2_even_desc_1027 = "「서술, 꿈의 세계를 떠도는 꿈을 먹는 그림자는 끊임없이 꿈을 갉아먹고, 그 폐허 위에 둥지를 짓습니다. 그 둥지를 깨끗이 제거해야만 꿈의 에너지가 다시 균형을 되찾을 수 있습니다.」\n\n계몽자는 언제나 당신을 위해 꿈의 세계의 규칙을 반복해서 설명해 주었다.\n\n「계몽자는 아버지에게 제안합니다. 꿈의 세계에서 충분한 꿈의 금화를 누적한 후, 둥지의 가장 깊은 곳에 있는 악몽의 독기에 도전해 보시기 바랍니다.」",
  str_season_maze_s2_even_desc_1028 = "「미약하지만 찬란한 가능성에 모든 것을 걸어 보거나, 안정된 삶을 누리며 순조로운 일생을 손에 넣거나.」\n\n이리돈은 앞을 바라보고 있었다. 자세히 살펴보지 않았다면, 그녀가 가볍게 자신의 입술을 물고 있음을 발견하지 못했을 것이다. 그 모습은 그녀가 깊은 생각을 할 때 늘 드러내는 표정이었다.\n\n「생각해 보면... 제 삶의 전반부는 후자였고, 후반부는 전자였어요. 그렇게 보면 정말 헛되지 않았네요.」",
  str_season_maze_s2_even_desc_1029 = "「이 세상의 모든 것에는 대가가 있어요. 가족 간의 사랑조차도 예외는 아니죠.」 이리돈은 눈을 내리깔고, 거의 반박할 수 없는 어조로 말했다.\n\n하지만 당신이 뭔가 말을 꺼내기 전, 그녀는 고개를 들고 웃으며 말했다. 「하지만 이젠 그 사람에게 돌려드릴 수 없어서 아쉽네요.」 당신은 알고 있었다. 이리돈이 말한 「그 사람」은 그녀의 아버지였다.\n\n「전 그 사람보다 더 나은 대심판관이 될 거예요. 그럼... 그 사람도 분명 기뻐하겠죠.」",
  str_season_maze_s2_even_desc_1030 = "「도주범이에요!」 이리돈은 지나가던 사람의 정체를 한눈에 알아차렸고, 남자는 이 말을 듣고 도망쳤다.\n\n「서둘러요! 앞의 두 길에서 흩어져서 포위하죠!」 당황한 당신의 표정을 본 이리돈은 주머니를 만졌다. 「여기 속도를 높일 수 있는 물건이 있어요. 너무 갑작스럽다는 건 알지만... 그래도 부탁할게요!」",
  str_season_maze_s2_help_tab_1 = "꿈의 잔향",
